    ('contexte-dernier-guide', "Repère sans style : dans ce conteneur, les balises lisent le dernier guide publié.", '--rl-repere: 1;'),
    ('contexte-prochain-webinar', "Repère sans style : dans ce conteneur, les balises lisent le prochain webinar.", '--rl-repere: 1;'),
    ('contexte-dernier-replay', "Repère sans style : dans ce conteneur, les balises lisent le dernier replay.", '--rl-repere: 1;'),
    ('contexte-rex', "Repère sans style : dans ce conteneur, les balises lisent le retour d'expérience lié au témoignage affiché (ou au témoignage de la réalisation affichée).", '--rl-repere: 1;'),
    ('contexte-webinar-ou-guide', "Repère sans style : dans ce conteneur, les balises lisent le prochain webinar, sinon le dernier guide (encart au milieu des articles).", '--rl-repere: 1;'),
    ('contexte-replay-ou-realisation', "Repère sans style : dans ce conteneur, les balises lisent le dernier replay, sinon la dernière réalisation (fin des articles).", '--rl-repere: 1;'),
    ('si-type--realisation', "Repère sans style : affiché seulement si le contenu lu est une réalisation.", '--rl-repere: 1;'),
    ('sans-temoignage-logo', "Repère sans style : affiché seulement si le guide n'a pas de témoignage lié avec un logo.", '--rl-repere: 1;'),
    ('si-contexte', "Repère sans style : affiché seulement si le conteneur « contexte-… » a trouvé un contenu publié.", '--rl-repere: 1;'),
    ('sans-image', "Repère sans style : affiché seulement quand le contenu n'a pas d'image à la une.", '--rl-repere: 1;'),
    ('sans-contexte', "Repère sans style : affiché seulement si la rubrique du conteneur « contexte-… » est encore vide.", '--rl-repere: 1;'),
    ('si-type--webinar', "Repère sans style : affiché seulement si le contenu lu est un webinar.", '--rl-repere: 1;'),
    ('si-type--guide', "Repère sans style : affiché seulement si le contenu lu est un guide.", '--rl-repere: 1;'),
    ('si-type--article', "Repère sans style : affiché seulement si le contenu lu est un article.", '--rl-repere: 1;'),
    ('ressources-grille', "Bloc Ressources : vignette à la une à gauche, rubriques à droite ; l'une sous l'autre sous 980 px.",
     'display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); gap: 24px; align-items: stretch; padding: 0; @media(--tablet) { grid-template-columns: minmax(0, 1fr); }'),
    ('ressource-une', "Conteneur de la vignette à la une (prend toute la hauteur de la grille).", 'display: flex; flex-direction: column; padding: 0; & > * { flex: 1; }'),
    ('une-photo', "Image de la vignette à la une (avec cadre-photo) : au moins 400 px de haut, plaque en bas.",
     'display: flex; flex-direction: column; justify-content: flex-end; min-height: 400px; height: 100%; padding: 20px; @media(--mobile) { min-height: 360px; padding: 12px; }'),
    ('une-sans-photo', "Fond de la vignette à la une quand il n'y a pas encore de ressource : dégradé de la charte au lieu d'une photo.",
     'background: radial-gradient(60% 70% at 85% 10%, rgba(255,138,91,0.55), rgba(255,138,91,0) 70%), radial-gradient(70% 80% at 0% 100%, rgba(91,59,234,0.9), rgba(91,59,234,0) 70%), linear-gradient(160deg, #2A1F5C, #16112C);'),
    ('plaque-une', "Plaque en verre fumé de la vignette à la une : textes empilés en blanc.",
     'position: relative; z-index: 2; display: flex; flex-direction: column; align-items: flex-start; gap: 8px; padding: 18px 20px; border-radius: 20px; color: #FFFFFF; background: linear-gradient(160deg, rgba(22,14,52,0.66) 0%, rgba(22,14,52,0.46) 100%), linear-gradient(rgba(0,0,0,0), rgba(0,0,0,0)); background-color: transparent; backdrop-filter: blur(18px) saturate(175%); box-shadow: inset 0 1px 0 rgba(255,255,255,0.85), inset 0 0 0 1px rgba(255,255,255,0.3), 0 14px 28px -14px rgba(10,6,30,0.6); @media(--mobile) { padding: 14px 16px; }'),
    ('titre-une', "Titre de la vignette à la une (blanc).", 'display: block; margin: 0; font-family: Bricolage Grotesque; font-size: 26px; line-height: 1.12; font-weight: 650; letter-spacing: -0.035em; color: #FFFFFF; @media(--mobile) { font-size: 21px; }'),
    ('texte-une', "Texte de la vignette à la une (lilas clair).", 'display: block; margin: 0; font-family: Hanken Grotesk; font-size: 15px; line-height: 1.45; color: #E9E2FF;'),
    ('grille-rubriques', "Grille des 4 rubriques (2 colonnes ; en liste, une par ligne, en mobile).", 'display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; padding: 0; @media(--mobile) { grid-template-columns: minmax(0, 1fr); gap: 10px; }'),
    ('carte-rubrique', "Carte d'une rubrique (avec carte-verre) : picto, titre, dernier contenu ou « Bientôt ». Plus discrète tant que la rubrique est vide. En mobile : une ligne de liste, picto à gauche.",
     "gap: 12px; padding: 22px; min-width: 0; transition: transform 0.4s cubic-bezier(0.2,0.8,0.2,1); &:not(:has(.si-contexte)) { background: rgba(255,255,255,0.45); box-shadow: inset 0 0 0 1px rgba(15,15,18,0.06); } &:not(:has(.si-contexte))::before { display: none; } &:not(:has(.si-contexte)) .picto-rubrique { opacity: 0.65; } @media(--mobile) { display: grid; grid-template-columns: 48px minmax(0, 1fr); column-gap: 16px; row-gap: 4px; align-content: center; padding: 16px 18px; border-radius: 20px; & > * { grid-column: 2; } & > .picto-rubrique { grid-column: 1; grid-row: 1 / span 3; align-self: start; } & .temoin-lien { margin-top: 4px; gap: 6px; font-size: 14px; text-align: left; justify-content: flex-start; } }"),
    ('picto-rubrique', "Picto en verre d'une rubrique (image de 96 px dont 24 px de marge pour l'ombre : le picto mesure 48 px) ; en mobile, à gauche sur la hauteur de la carte.", 'display: block; width: 96px; height: auto; margin: -24px; max-width: none;', '@media (max-width: 767px) { grid-column: 1; grid-row: 1 / span 3; align-self: start; }'),
    ('etiquette-bientot', "Pastille grise « Bientôt » (rubrique encore vide).", 'display: block; width: fit-content; margin: 0; padding: 4px 10px; border-radius: 999px; font-family: Hanken Grotesk; font-size: 12px; line-height: 1.3; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: #5C5A68; background: rgba(15,15,18,0.06);'),
    ('texte-herite', "Texte qui reprend la police, la taille, la graisse et la couleur de son parent (ex. le titre H1 posé dans la pastille du hero).", 'margin: 0;', 'font-family: inherit; font-size: inherit; font-weight: inherit; line-height: inherit; letter-spacing: inherit; color: inherit;'),
    ('hero-montage', "Visuels du hero en mobile (sous 768 px) : les vignettes s'enchaînent dans un seul cadre (3 s chacune, dans l'ordre), avec des barres de progression façon stories en haut et un timecode. Sans effet sur ordinateur et tablette.",
     "@media(--mobile) { display: block; height: 400px; margin-top: 4px; isolation: isolate; "
     "&::before { " + RAZ + "content: '00:' counter(rl-s, decimal-leading-zero) ' / 00:12' / ''; position: absolute; top: 34px; right: 22px; bottom: auto; left: auto; z-index: 3; width: auto; height: auto; padding: 4px 9px; border-radius: 999px; pointer-events: none; "
     "font-family: Hanken Grotesk; font-size: 12px; line-height: 1; font-weight: 700; font-variant-numeric: tabular-nums; color: #FFFFFF; background: rgba(22,14,52,0.66); box-shadow: none; counter-reset: rl-s var(--rl-s); animation: rl-secondes-hero 12s linear infinite; } "
     "&::after { content: ''; position: absolute; top: 20px; right: 22px; left: 22px; z-index: 3; height: 4px; border-radius: 4px; pointer-events: none; "
     "background: linear-gradient(#FFFFFF, #FFFFFF) 0 0 / 25% 100% no-repeat, rgba(255,255,255,0.42); "
     "-webkit-mask: repeating-linear-gradient(90deg, #000 0 calc(25% - 4px), transparent calc(25% - 4px) 25%); mask: repeating-linear-gradient(90deg, #000 0 calc(25% - 4px), transparent calc(25% - 4px) 25%); animation: rl-stories-hero 12s linear infinite; } "
     "& > .e-con { position: absolute; top: 0; right: 0; bottom: 0; left: 0; width: auto; align-self: stretch; justify-self: stretch; z-index: 1; opacity: 0; padding: 10px; border-radius: 30px; --rl-rayon-photo: 21px; --rl-marge-vignette: 10px; animation: rl-plan-hero 12s infinite; } "
     "& > .e-con:nth-last-child(4) { opacity: 1; } & > .e-con:nth-last-child(3) { animation-delay: 3s; } & > .e-con:nth-last-child(2) { animation-delay: 6s; } & > .e-con:nth-last-child(1) { animation-delay: 9s; } "
     "& > .e-con > .e-con { height: 100%; aspect-ratio: auto; } & .bandeau-video { top: 24px; } }"),
    ('motion-formes', "Vignette motion design en mobile : fond pêche et formes qui s'animent (rond qui rebondit, carré qui pivote). Avec mot-motion pour le triangle et le trait. Sans effet sur ordinateur et tablette.",
     "@media(--mobile) { display: flex; flex-direction: column; justify-content: flex-end; padding: 0 18px 86px; background: linear-gradient(#FFF1E7, #FFF1E7); "
     "&::before { " + RAZ + "content: ''; position: absolute; z-index: 0; top: 66px; right: auto; bottom: auto; left: 18px; width: 92px; height: 92px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #FFFFFF, #FFD1BF 55%, #FF8A5B); box-shadow: 0 14px 26px -14px rgba(166,60,20,0.55); animation: rl-forme-rebond 3s cubic-bezier(0.3,0,0.3,1) infinite; } "
     "&::after { content: ''; position: absolute; z-index: 0; top: 76px; right: 34px; bottom: auto; left: auto; width: 74px; height: 74px; border-radius: 20px; background: linear-gradient(140deg, #5B3BEA, #8E4DE6); box-shadow: 0 14px 26px -14px rgba(74,43,184,0.6); animation: rl-forme-tourne 3s cubic-bezier(0.6,0,0.2,1) infinite; } }"),
    ('mot-motion', "Grand mot de la vignette motion design en mobile (ex. « Résultats 2026 »), avec un triangle qui tombe et un trait qui s'allonge. Masqué sur ordinateur et tablette.",
     "display: none; @media(--mobile) { display: block; position: static; margin: 0; font-family: Bricolage Grotesque; font-size: 26px; line-height: 1; font-weight: 700; letter-spacing: -0.05em; color: #0F0F12; animation: rl-forme-mot 3s ease-out infinite; "
     "&::before { content: ''; position: absolute; z-index: 0; top: 140px; left: 44%; width: 0; height: 0; border-left: 34px solid transparent; border-right: 34px solid transparent; border-bottom: 58px solid #3434E0; animation: rl-forme-tombe 3s cubic-bezier(0.3,1.4,0.5,1) infinite; } "
     "&::after { content: ''; display: block; margin-top: 12px; width: 190px; max-width: 70%; height: 22px; border-radius: 999px; background: #E0562A; animation: rl-forme-allonge 3s cubic-bezier(0.2,0.9,0.2,1) infinite; } }"),
    ('showreel-grandit', "Cadre du showreel qui grandit au défilement (de 72 % à 100 % de la largeur ; de 88 % en mobile). Navigateurs sans cette fonction : affiché directement en grand.",
     "align-self: center; width: 100%; --rl-depart: 72%; @media(--mobile) { --rl-depart: 88%; }",
     "animation: rl-showreel-grandit auto linear both; animation-timeline: view(); animation-range: entry 0% cover 45%;"),
    ('apparait-defile', "Apparaît en fondu en remontant légèrement quand on le fait défiler dans l'écran (ex. boutons sous le showreel).",
     "--rl-repere: 1;", "animation: rl-apparait-defile auto linear both; animation-timeline: view(); animation-range: entry 0% entry 100%;"),
    ('entete-page', "Haut d'une page intérieure (avec section-entete) : plus d'air sous l'en-tête.", 'padding: 184px 0 56px; @media(--tablet) { padding: 160px 0 48px; } @media(--mobile) { padding: 136px 0 40px; }'),
    ('appel-centre', "Bandeau d'appel (avec carte-verre et carte-appel) en grand et centré, au milieu d'une page.", 'justify-content: center; gap: 18px 28px; padding: 48px; border-radius: 40px; text-align: center; @media(--mobile) { padding: 28px; border-radius: 32px; }'),
    ('titre-encart', "Titre d'un encart d'appel (avec titre-xs) : un peu plus grand.", 'font-size: 28px; @media(--mobile) { font-size: 24px; }'),

    # Offres : tableau comparatif (colonne « Création + Tournage » sur fond sombre = pseudo-élément du tableau).
    ('offres-tableau', "Tableau des formules (avec carte-pleine) : la colonne de droite est posée sur une bande sombre.",
     "border-radius: 34px; gap: 0; padding: 0 0 8px; &::before { " + RAZ + "content: ''; position: absolute; z-index: 0; top: 8px; bottom: 8px; right: 8px; left: auto; width: 262px; height: auto; border-radius: 28px; background: radial-gradient(90% 16% at 85% 0%, rgba(255,138,91,0.42), rgba(255,138,91,0) 70%), radial-gradient(80% 16% at 0% 100%, rgba(139,92,246,0.45), rgba(139,92,246,0) 70%), linear-gradient(180deg, #1C1730 0%, #0F0F12 100%); box-shadow: inset 0 1px 0 rgba(255,255,255,0.2); } @media(--mobile) { &::before { width: 84px; } }"),
    ('offres-badge', "« Le plus complet » posé sur le haut de la colonne sombre.", 'position: absolute; z-index: 3; top: -14px; right: 87px; width: fit-content; padding: 6px 14px; border-radius: 999px; font-family: Hanken Grotesk; font-size: 12px; line-height: 1.2; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: #0F0F12; background: #FFD1BF; @media(--mobile) { right: 6px; padding: 5px 10px; }'),
    ('offres-ligne', "Ligne du tableau : libellé, puis une case par formule (la 3e sur fond sombre).",
     "position: relative; z-index: 1; display: grid; grid-template-columns: minmax(0, 1fr) 250px 262px; gap: 0; padding: 0 8px 0 0; "
     "& > * { display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 2px; padding: 9px 24px; font-family: Hanken Grotesk; font-size: 15.5px; line-height: 1.4; text-align: center; color: var(--encre); border-top: 1px solid rgba(15,15,18,0.07); } "
     "& > :nth-last-child(3) { align-items: flex-start; padding-left: 36px; text-align: left; } "
     "& > :last-child { color: #ECE8F7; border-top-color: rgba(255,255,255,0.08); --rl-texte: #FFFFFF; --rl-legende: #B6B0CC; } & > :last-child:not(:only-child) { background-color: #1C1730; -webkit-background-clip: text; background-clip: text; } "
     "@media(--mobile) { grid-template-columns: minmax(0, 1fr) 76px 84px; & > *, & > :nth-last-child(3) { padding: 10px 8px; font-size: 14px; } & > :nth-last-child(3) { padding-left: 14px; } }"),
    ('offres-groupe', "Ligne de titre de groupe dans le tableau (avec offres-ligne) : une seule case, dans la première colonne.", '& > * { align-items: flex-start; padding-top: 26px; padding-bottom: 6px; padding-left: 36px; text-align: left; border-top: 0; } @media(--mobile) { & > * { padding-left: 14px; padding-right: 8px; } & .label { letter-spacing: 0.08em; line-height: 1.35; } }'),
    ('offres-entete', "Première ligne du tableau (avec offres-ligne) : titre, nom, prix et bouton de chaque formule.", '& > * { justify-content: flex-start; gap: 8px; padding-top: 34px; padding-bottom: 26px; border-top: 0; } & > :last-child { border-top: 0; } @media(--mobile) { & > :nth-last-child(3) { grid-column: 1 / 3; padding-top: 30px; padding-bottom: 6px; } & > :nth-last-child(2), & > :last-child { align-self: end; padding-top: 10px; padding-bottom: 18px; } & > :nth-last-child(2) { grid-column: 2; } & > :last-child { grid-column: 3; } }'),
    ('offres-detail', "Précision sous un libellé du tableau, en petit.", 'display: block; font-family: Hanken Grotesk; font-size: 13px; line-height: 1.4; color: var(--rl-legende, var(--legende));'),
    ('offres-prix', "Prix d'une formule dans le tableau (le span = « / mois » en petit).", 'display: block; font-family: Bricolage Grotesque; font-size: 38px; line-height: 1.1; font-weight: 650; letter-spacing: -0.04em; color: var(--rl-texte, var(--encre)); & span { font-family: Hanken Grotesk; font-size: 14px; letter-spacing: 0; font-weight: 400; color: var(--rl-legende, var(--legende)); }'),
    ('offres-resume', "Résumé d'une formule dans le tableau, sur fond lilas.", 'display: block; width: 100%; margin-top: 4px; padding: 8px 10px; border-radius: 12px; font-family: Hanken Grotesk; font-size: 13px; line-height: 1.35; font-weight: 600; color: #4A2BB8; background: #EDE6FF;'),
    ('offres-resume-sombre', "Résumé de la formule sombre (avec offres-resume).", 'color: #ECE8F7; background: linear-gradient(rgba(255,255,255,0.08), rgba(255,255,255,0.08)), linear-gradient(rgba(0,0,0,0), rgba(0,0,0,0)); background-color: transparent; box-shadow: inset 0 0 0 1px rgba(255,255,255,0.14);'),
    ('offres-masquer', "Masqué sur mobile (prix et boutons du haut du tableau : ils passent sous le tableau).", '@media(--mobile) { display: none; }'),
    ('offres-mobile', "Cartes prix sous le tableau, visibles sur mobile seulement.", 'display: none; @media(--mobile) { display: grid; }'),
    ('titre-formule', "Nom d'une formule en tête de tableau (avec titre-xs).", 'font-size: 21px; @media(--mobile) { font-size: 15px; }'),
    ('case-oui', "Coche « Inclus » dans le tableau.", 'display: block; width: 26px; height: 26px; margin: 0 auto; filter: drop-shadow(0 3px 6px rgba(91,59,234,0.28));'),
    ('case-non', "Croix « Non inclus » dans le tableau (le texte est masqué, une croix grise le remplace).", "position: relative; display: block; width: 22px; height: 22px; margin: 0 auto; overflow: hidden; border-radius: 50%; font-size: 0; color: transparent; background: rgba(15,15,18,0.06); &::before, &::after { content: ''; position: absolute; top: 10px; left: 6px; width: 10px; height: 2px; border-radius: 2px; background: #6E6B7B; transform: rotate(45deg); } &::after { transform: rotate(-45deg); }"),

    # Frise de montage (offres, L'agence) : règle de timecodes, clips colorés, tête de lecture rouge.
    ('montage', "Frise de montage (avec carte-verre) : règle, clips, et une tête de lecture rouge qui avance jusqu'au dernier clip.",
     "gap: 0; margin-top: 8px; padding: 22px 26px 34px; border-radius: 30px; overflow: hidden; "
     "&::before { " + RAZ + "content: ''; position: absolute; z-index: 2; top: 36px; left: 18px; right: auto; bottom: auto; width: 16px; height: 20px; padding: 0; pointer-events: none; background: linear-gradient(90deg, transparent 7px, rgba(255,255,255,0.9) 7px 9px, transparent 9px) center 4px / 16px 8px no-repeat, linear-gradient(180deg, #FF6A5F, #FF3B30); clip-path: polygon(0 0, 100% 0, 100% 62%, 50% 100%, 0 62%); border-radius: 4px 4px 0 0; box-shadow: none; transition: left 2.4s cubic-bezier(0.4, 0, 0.2, 1) 0.3s; } "
     "&::after { content: ''; position: absolute; z-index: 2; top: 54px; left: 25px; width: 2px; height: 112px; pointer-events: none; background: linear-gradient(180deg, #FF3B30 0%, #FF3B30 82%, rgba(255,59,48,0) 100%); box-shadow: 0 0 10px rgba(255,59,48,0.45); transition: left 2.4s cubic-bezier(0.4, 0, 0.2, 1) 0.3s; } "
     "&.vu::before { left: calc(100% - 38px); } &.vu::after { left: calc(100% - 31px); } "
     "@media(--tablet) { padding: 20px 20px 26px; &::before, &::after { display: none; } }"),
    ('montage-regle', "Règle de timecodes en haut de la frise (deux textes : début et fin).", 'display: flex; flex-direction: row; justify-content: space-between; padding: 0 44px 26px 0; font-family: Bricolage Grotesque; font-size: 12px; font-weight: 650; letter-spacing: 0.08em; color: var(--rl-legende, var(--legende)); background: repeating-linear-gradient(90deg, rgba(91,59,234,0.28) 0 1px, transparent 1px 24px) left 22px / 100% 8px no-repeat, repeating-linear-gradient(90deg, rgba(91,59,234,0.45) 0 1px, transparent 1px 120px) left 18px / 100% 12px no-repeat; @media(--tablet) { padding: 0 0 18px 30px; background: none; }'),
    ('montage-piste', "Piste des clips (3 colonnes ; en mobile, une colonne le long d'une règle verticale).",
     "position: relative; display: grid; grid-template-columns: 1.15fr 1fr 1.3fr; gap: 10px; padding: 0; "
     "@media(--tablet) { grid-template-columns: minmax(0, 1fr); gap: 30px; padding-left: 30px; &::before { " + RAZ + "content: ''; position: absolute; top: 0; bottom: 0; left: 6px; right: auto; width: 10px; height: auto; background: linear-gradient(90deg, transparent 4px, rgba(91,59,234,0.3) 4px 6px, transparent 6px), repeating-linear-gradient(180deg, rgba(91,59,234,0.35) 0 1px, transparent 1px 14px); } }"),
    ('montage-4', "Frise à 4 clips (avec montage-piste).", 'grid-template-columns: repeat(4, minmax(0, 1fr)); @media(--tablet) { grid-template-columns: minmax(0, 1fr); }'),
    ('clip', "Un clip de la frise : barre colorée, titre, texte.",
     "display: flex; flex-direction: column; gap: 10px; padding: 0; & > :not(.clip-barre) { padding-right: 12px; } "
     "@media(--tablet) { &::before { " + RAZ + "content: ''; position: absolute; top: 25px; left: -29px; right: auto; bottom: auto; width: 14px; height: 14px; border-radius: 50%; background: #FFFFFF; box-shadow: 0 0 0 3px rgba(91,59,234,0.45); } }"),
    ('clip-barre', "Barre colorée d'un clip, avec sa forme d'onde.",
     "position: relative; display: flex; flex-direction: row; align-items: center; gap: 10px; min-height: 64px; margin-bottom: 10px; padding: 0 16px; border-radius: 14px; overflow: hidden; font-family: Hanken Grotesk; font-size: 14px; font-weight: 700; color: #FFFFFF; background: linear-gradient(100deg, #3434E0, #5B3BEA); background-color: #3434E0; box-shadow: inset 0 1px 0 rgba(255,255,255,0.35), 0 14px 30px -18px rgba(76,48,170,0.7); "
     "&::before { " + RAZ + "content: ''; position: absolute; top: auto; right: 0; bottom: 0; left: 0; width: auto; height: 22px; opacity: 0.35; background: repeating-linear-gradient(90deg, #FFFFFF 0 2px, transparent 2px 6px); -webkit-mask: linear-gradient(0deg, #000 0%, transparent 100%); mask: linear-gradient(0deg, #000 0%, transparent 100%); } & > * { position: relative; } "
     "@media(--mobile) { flex-wrap: wrap; gap: 6px 8px; padding: 10px 12px; }"),
    ('clip-numero', "« Clip 01 » dans la barre.", 'flex-shrink: 0; width: fit-content; padding: 4px 9px; border-radius: 999px; font-family: Hanken Grotesk; font-size: 12px; line-height: 1.2; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; white-space: nowrap; color: #FFFFFF; background: rgba(15,15,18,0.62);'),
    ('clip-nom', "Nom du clip dans la barre.", 'font-family: Hanken Grotesk; font-size: 14px; line-height: 1.3; font-weight: 700; color: inherit; @media(--mobile) { order: 3; flex: 1 0 100%; }'),
    ('clip-rec', "« En cours » avec un point rouge, à droite de la barre.", "display: inline-flex; flex-direction: row; align-items: center; gap: 7px; flex-shrink: 0; margin-left: auto; padding: 4px 10px; border-radius: 999px; font-family: Hanken Grotesk; font-size: 12px; line-height: 1.2; font-weight: 700; white-space: nowrap; color: #FFFFFF; background: rgba(15,15,18,0.72); &::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: #FF3B30; animation: rl-clignote 1.6s ease-in-out infinite; } @media(--mobile) { order: 2; }"),
    ('clip-demande', "Couleur du 2e clip (violet).", '& .clip-barre { background: linear-gradient(100deg, #5B3BEA, #7A45E0); background-color: #5B3BEA; }'),
