    ('cadre-storyboard', "Visuel « storyboard » : fond pêche et annotation manuscrite au centre (remplaçable par une image) ; l'annotation reste visible en mobile.", 'position: relative; display: flex; align-items: center; justify-content: center; aspect-ratio: 16 / 10; padding: 0; border-radius: 20px; overflow: hidden; background: linear-gradient(160deg, #FFE7DA, #FFD1BF); @media(--tablet) { & .note-main { display: block; font-size: 27px; } }'),
